function patchIndex(source) {
  let html=source.replace(/\r\n?/g,'\n');
  if (html.includes('// Thumbnail/Search upgrade v1')) throw new Error('この更新は適用済みです。未変更です。');
  for (const {before,after} of PATCHES) {
    if (html.split(before).length!==2) throw new Error('対象コードが一致しません。未変更です。最新のindex.htmlを確認してください: '+before.slice(0,70));
    html=html.replace(before,() => after);
  }
  const hashes=[...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)]
    .filter(match => !/\bsrc\s*=/i.test(match[1])).map(match => {
      const checked=spawnSync(process.execPath,['--check','--input-type=module'],{input:match[2],encoding:'utf8'});
      if(checked.status!==0) throw new Error('JavaScriptの構文確認に失敗しました。未変更です。\n'+checked.stderr);
      return "'sha256-"+crypto.createHash('sha256').update(match[2]).digest('base64')+"'";
    });
  const meta=html.match(/<meta\b[^>]*http-equiv="Content-Security-Policy"[^>]*>/i)?.[0];
  if(!meta || !/script-src\s+[^;]+;/.test(meta)) throw new Error('CSPを確認できません。未変更です。');
  const updated=meta.replace(/(script-src\s+)([^;]+)(;)/,(_all,prefix,value,suffix) =>
    prefix+value.replace(/\s*'sha256-[^']+'/g,'').trim()+' '+[...new Set(hashes)].join(' ')+suffix);
  return html.replace(meta,() => updated);
}
function install(directory='.') {
  const root=path.resolve(directory), index=path.join(root,'index.html');
  const updated=patchIndex(fs.readFileSync(index,'utf8'));
  const entries=Object.entries(SERVER_FILES).map(([filename,content]) => ({filename,target:path.join(root,filename),content}));
  for (const entry of entries) {
    if(fs.existsSync(entry.target) && fs.readFileSync(entry.target,'utf8')!==entry.content) throw new Error('既存の別バージョンを上書きできません。未変更です: '+entry.filename);
  }
  const serverCheck=spawnSync(process.execPath,['--check'],{input:SERVER_FILES['thumbnail-server/functions/index.js'],encoding:'utf8'});
  if(serverCheck.status!==0) throw new Error(serverCheck.stderr);
  const backup=fs.mkdtempSync(path.join(os.tmpdir(),'submovie-thumbnail-search-backup-'));
  fs.copyFileSync(index,path.join(backup,'index.html'));
  const created=[];
  try {
    for (const entry of entries) {
      if(fs.existsSync(entry.target)) continue;
      fs.mkdirSync(path.dirname(entry.target),{recursive:true}); fs.writeFileSync(entry.target,entry.content,'utf8'); created.push(entry.target);
    }
    fs.writeFileSync(index,updated,'utf8');
  } catch(error) {
    fs.copyFileSync(path.join(backup,'index.html'),index);
    for(const target of created.reverse()) fs.rmSync(target,{force:true});
    throw error;
  }
  console.log('更新しました: index.html');
  console.log('追加しました: thumbnail-server （既存のanti-spam-server等は未変更）');
  console.log('バックアップ: '+path.join(backup,'index.html'));
  console.log('次はREADMEの手順で新しいFunctionsをデプロイし、GitHubへプッシュしてください。');
}
if(require.main===module) { try { install(process.argv[2]); } catch(error) { console.error(error.message); process.exitCode=1; } }
module.exports={patchIndex,install};
